extern "C" int sprintf(char *, const char *, ...);

int random(int);

class stringx
{
  char *chars;
  void *my_buf;
public:
  stringx(const char *, int = -1);
  ~stringx();
  const char *c_str() const { return chars; }
};

class entity_anim_tree
{
public:
  bool is_finished() const;
  bool is_done_tween() const;
  float get_time_remaining() const;
  float get_duration() const;
};

class entity
{
public:
  entity_anim_tree *get_anim_tree(int);
  void *play_anim(int, const stringx &, float, unsigned short = 0, short = -1);
};

class generic_anim_animal
{
  stringx my_base_name;
  int cur_state, cur_anim;
  bool dummy;
  bool left_down, right_down;
  char pad[5];
  int generic_anims[2];
  int generic_anim_state;
  entity *my_entity;

  static const char *generic_anim_names[];
  enum { AA_IDLE, AA_DIVE, AA_SPAWN };
public:
  void update(bool collide, bool jump, bool spray, float *alpha);
};

void generic_anim_animal::update (bool collide, bool jump, bool spray, float *alpha)
{
  entity_anim_tree* anim_tree = my_entity->get_anim_tree (0);
  int play = -1;

  if (generic_anim_state == AA_SPAWN)
  {
    play = generic_anim_state = AA_IDLE;
  }
  else if ((generic_anim_state == AA_IDLE) && (collide || jump || spray))
  {
    // check for collision/spray/jump
    if (collide || jump || spray)
    {
      generic_anim_state = play = AA_DIVE;
    }
  }
  else if (anim_tree && anim_tree->is_finished () && anim_tree->is_done_tween ())
  {
    switch (generic_anim_state)
    {
    case AA_IDLE: generic_anim_state = AA_IDLE; break;
    case AA_DIVE: generic_anim_state = AA_IDLE; break;
    }
    play = generic_anim_state;
  }

  if ((play != -1) && (generic_anims[play] > 0))
  {
    char anim[256];
    sprintf (anim, "%s_%s_%d", my_base_name.c_str (), generic_anim_names[play], random(generic_anims[play]) + 1);

    my_entity->play_anim (0, anim, 0.3f, 0x0a00);
  }

	if (generic_anim_state == AA_DIVE)
	{
		*alpha = anim_tree->get_time_remaining () / anim_tree->get_duration ();
	}
}
